using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Positional;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Positional;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.OrbitalAndPositional;
public sealed class AstronomyCartesianPositionValidationRuleTests { [Fact] public void Valid_cartesian_position_and_zero_vector_pass() => Assert.Empty(new AstronomyCartesianPositionValidationRule().Validate(OrbitalPositionalValidationFixture.CartesianPayload(), OrbitalPositionalValidationFixture.Context())); [Fact] public void Cartesian_component_dimension_and_mixed_units_are_constructor_protected() { Assert.Throws<ArgumentException>(() => new AstronomyCartesianCoordinate(OrbitalPositionalValidationFixture.Measure(1, AstronomyMeasurementDimension.Angle, "deg"), OrbitalPositionalValidationFixture.Measure(1, AstronomyMeasurementDimension.Angle, "deg"), OrbitalPositionalValidationFixture.Measure(1, AstronomyMeasurementDimension.Angle, "deg"))); Assert.Throws<ArgumentException>(() => new AstronomyCartesianCoordinate(OrbitalPositionalValidationFixture.Measure(1, AstronomyMeasurementDimension.Distance, "km"), OrbitalPositionalValidationFixture.Measure(1, AstronomyMeasurementDimension.Distance, "m"), OrbitalPositionalValidationFixture.Measure(1, AstronomyMeasurementDimension.Distance, "km"))); } }
